def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    pressured_bids = []
    rich_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_count += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace') or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 4 or opp.get('no_water_days', 0) >= 1:
                    pressured_bids.append(float(bid))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    capacity = supply / float(WATER_REQ)
    tight = capacity < (1 + 0.35 * len(alive))
    roomy = capacity > (1 + 0.6 * len(alive))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_prev = max(pressured_bids) if pressured_bids else highest_prev

    base = DAILY_SALARY * 0.42

    if roomy:
        base = DAILY_SALARY * 0.28
    elif tight:
        base = DAILY_SALARY * 0.68

    if rich_count >= 2:
        base += 8.0
    elif rich_count == 0:
        base -= 6.0

    if desperate_count >= 2:
        base += 10.0

    if highest_prev > 0:
        if highest_prev >= DAILY_SALARY * 1.5:
            target = DAILY_SALARY * 0.52 if hp > 4 and no_water_days == 0 else DAILY_SALARY * 0.92
        elif highest_prev >= DAILY_SALARY * 0.95:
            target = max(base, pressure_prev + 2.5)
        else:
            target = max(base, highest_prev + 1.5)
    else:
        target = base

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 1.02)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.82)

    if day >= 8:
        target += 6.0
    if day == 10:
        target += 10.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0 and day < 8:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.08

    spendable = max(0.0, budget - reserve_floor)
    if spendable <= 0:
        spendable = budget * 0.5

    bid = min(target, spendable, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', MIN_SUPPLY))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids (only immediate reaction)
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Identify Cindy's yesterday bid as a proxy for aggressive pressure
    cindy_prev = opponents_status.get('Cindy', {}).get('previous_trace', {}) or {}
    cindy_bid = cindy_prev.get('bid', None)
    try:
        cindy_bid = float(cindy_bid) if cindy_bid is not None else None
    except Exception:
        cindy_bid = None

    # Decide base bid level
    # If Cindy was aggressive, we slightly undercut to avoid overpaying, but still bid enough to secure water.
    if cindy_bid is not None:
        if cindy_bid >= DAILY_SALARY * 1.1:
            # Cindy likely willing to pay; avoid matching her full amount.
            target = cindy_bid * 0.85
        elif cindy_bid >= DAILY_SALARY * 0.85:
            target = cindy_bid * 0.8
        else:
            target = max(DAILY_SALARY * 0.45, cindy_bid + 5.0)
    else:
        if yesterday_bids:
            highest_prev = max(yesterday_bids)
            # If someone was very high, don't chase fully.
            if highest_prev >= DAILY_SALARY * 0.9:
                target = highest_prev * 0.75
            else:
                target = max(DAILY_SALARY * 0.55, highest_prev + 2.0)
        else:
            target = DAILY_SALARY * 0.55

    # Scale by our urgency
    # Lower HP / more no-water days -> bid higher.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 0.35
    elif my_hp <= 4:
        urgency = 0.2
    elif my_hp <= 6:
        urgency = 0.1

    if my_no_water_days >= 2:
        urgency += 0.15
    if my_no_water_days >= 4:
        urgency += 0.25

    # Supply-based adjustment: with more supply, we can bid less.
    # Convert to a rough fraction of max supply.
    supply_frac = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_frac = max(0.0, min(1.0, supply_frac))

    # If supply is low, increase bid; if high, decrease.
    supply_factor = 1.0 + (0.5 - supply_frac) * 0.35  # ranges ~1.175 to 0.825

    target = target * (1.0 + urgency) * supply_factor

    # Hard caps to avoid bankruptcy.
    # In this meta, aggressive bidding drained others; keep a safety reserve.
    safety_reserve = DAILY_SALARY * 0.2
    max_affordable = max(0.0, my_budget - safety_reserve)

    # Also cap to a reasonable multiple to avoid matching Cindy too closely.
    # Since Cindy max bid was ~127.5, keep below ~1.45 salary.
    hard_cap = DAILY_SALARY * 1.45

    bid = min(target, max_affordable, hard_cap, my_budget)

    # If we are very low HP, allow a larger fraction of budget.
    if my_hp <= 2 and my_budget > 0:
        bid = min(my_budget, max(bid, DAILY_SALARY * 0.9))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if hp <= 2:
        base_bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base_bid = min(budget, DAILY_SALARY * 0.7)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.5)

    # Adjust based on yesterday's highest pressure
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.85:
            if hp > 3:
                base_bid = min(budget, highest_prev * 0.95)  # slightly undercut if safe
            else:
                base_bid = min(budget, highest_prev + 5)  # match or exceed
        else:
            base_bid = min(budget, max(base_bid, highest_prev + 1.5))

    # Supply-based adjustment
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0 to 1
    if supply_ratio < 0.3:
        base_bid = min(budget, base_bid * 1.2)

    # Ensure we don't bid more than budget
    final_bid = min(budget, base_bid)
    return int(final_bid)
